import type { Lesson, Unit } from './schema';

/**
 * Light course index (ADR-012): enough to draw the path, guard routes and count due cards
 * without importing any unit JSON. Generated by `npm run validate:content` into
 * `manifest.generated.ts`; `manifest.test.ts` fails if it drifts from the real content.
 */
export type ManifestLesson = {
  id: string;
  title?: string;
  exerciseCount: number;
  /** Items practiced by the lesson, unique, in exercise order (Practice reserve, ADR-011). */
  itemIds: string[];
};

export type ManifestSkill = {
  id: string;
  title: string;
  icon: string;
  lessons: ManifestLesson[];
  /** Vocab + sentence ids, in content order. */
  itemIds: string[];
};

export type ManifestUnit = {
  id: string;
  order: number;
  title: string;
  color: Unit['color'];
  /** File name inside src/content/units (key of the lazy glob). */
  file: string;
  skills: ManifestSkill[];
  reviewLesson: ManifestLesson;
};

export type CourseManifest = { units: ManifestUnit[] };

/** Builds the manifest from validated units (`files[i]` is the JSON file of `units[i]`). */
export function buildManifest(units: readonly { unit: Unit; file: string }[]): CourseManifest {
  const sorted = [...units].sort((a, b) => a.unit.order - b.unit.order);
  return {
    units: sorted.map(({ unit, file }) => ({
      id: unit.id,
      order: unit.order,
      title: unit.title,
      color: unit.color,
      file,
      skills: unit.skills.map((skill) => ({
        id: skill.id,
        title: skill.title,
        icon: skill.icon,
        lessons: skill.lessons.map(manifestLesson),
        itemIds: [...skill.vocab, ...skill.sentences].map((i) => i.id),
      })),
      reviewLesson: manifestLesson(unit.reviewLesson),
    })),
  };
}

function manifestLesson(lesson: Lesson): ManifestLesson {
  return {
    id: lesson.id,
    ...(lesson.title !== undefined ? { title: lesson.title } : {}),
    exerciseCount: lesson.exercises.length,
    itemIds: [...new Set(lesson.exercises.flatMap((e) => e.itemIds))],
  };
}

/** Exercises that cite items of another unit (lazy loading opens only the lesson's own unit). */
export function crossUnitReferences(unit: Unit): string[] {
  const own = new Set(unit.skills.flatMap((s) => [...s.vocab, ...s.sentences].map((i) => i.id)));
  const issues: string[] = [];
  for (const lesson of [...unit.skills.flatMap((s) => s.lessons), unit.reviewLesson]) {
    for (const ex of lesson.exercises) {
      for (const ref of ex.itemIds) {
        if (!own.has(ref))
          issues.push(`Exercício ${ex.id} cita o item "${ref}", de outra unidade.`);
      }
    }
  }
  return issues;
}
